/// <summary>
/// Concrete class for calculating MDF based on WMSOrderTrans
/// </summary>
public class METCustomerMDFCalculation_WMSOrderTrans extends METCustomerMDFCalculation
{
    container packedMap;

}

Method.Source:
/// <summary>
/// Update query for processing
/// </summary>
/// <param name = "_query">Query</param>
/// <returns>Query</returns>
Query updateQuery(Query _query)
{
    Query ret = super(_query);

    QueryBuildDataSource qbds = ret.dataSourceTable(tableNum(WMSOrderTrans));

    this.addWMSOrderTransRecIdRange(packedMap, qbds);

    return ret;
}

/// <summary>
/// Add WMSOrderTrans RecId range to the query
/// </summary>
/// <param name = "_packedMap">container</param>
/// <param name = "_qbds">QueryBuildDataSource</param>
private void addWMSOrderTransRecIdRange(container _packedMap, QueryBuildDataSource _qbds)
{
    if (!_packedMap)
    {
        return;
    }

    Map selectedWMSOrderTrans = Map::create(_packedMap);

    if (!selectedWMSOrderTrans)
    {
        return;
    }

    MapEnumerator metListEnumerator = selectedWMSOrderTrans.getEnumerator();

    while (metListEnumerator.moveNext())
    {
        RecId wMSOrderTransRecId = metListEnumerator.currentKey();
        _qbds.addRange(fieldNum(WMSOrderTrans, RecId)).value(queryValue(wMSOrderTransRecId));
    }
}

/// <summary>
/// Parameter packed map
/// </summary>
/// <param name = "_packedMap">container</param>
/// <returns>container</returns>
public container parmWMSOrderTransMulti(container _packedMap = packedMap)
{
    packedMap = _packedMap;

    return packedMap;
}
